-- Owned synthetic actors only; no provider, authentication request or delivery.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temp table access_state(key text primary key,value jsonb);
create function pg_temp.access_actor(actor uuid) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true)::text is not null$$;
create function pg_temp.access_cmd(slug text,cmd text,body jsonb default '{}',key uuid default gen_random_uuid()) returns jsonb language sql as $$select api.frightnight_command(slug,cmd,body,key)$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)
select ('f7320000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'access-'||n||'@example.invalid',case when n=6 then null else now() end,'{}','{}' from generate_series(1,9)n;
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id='f7320000-0000-0000-0000-000000000007';
update auth.users set deleted_at=clock_timestamp() where id='f7320000-0000-0000-0000-000000000008';
insert into app_private.events(id,slug,title,local_date,price_cents) values('f7320000-0000-0000-0000-000000000010','access-local-legacy','Local synthetic access fixture','2026-10-31',350);
insert into app_private.event_capabilities(event_id,user_id,capability) values('f7320000-0000-0000-0000-000000000010','f7320000-0000-0000-0000-000000000001','event_admin');
select api.frightnight_bootstrap('frightnight-2027-test','f7320000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg') is not null;
select api.frightnight_bootstrap('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg') is not null;
select api.frightnight_bootstrap('frightnight-2027-test-access-b','f7320000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg') is not null;
insert into access_state select 'before',jsonb_build_object('households',(select count(*)from app_private.households),'outbox',(select count(*)from app_private.email_outbox),'orders',(select count(*)from app_private.fn_orders));
select ok(not has_function_privilege('authenticated','api.frightnight_entry_grant(text,uuid,timestamptz,text)','EXECUTE'),'browser cannot mint a private edition entry');
select ok(has_function_privilege('service_role','api.frightnight_entry_grant(text,uuid,timestamptz,text)','EXECUTE'),'trusted application can record validated entry');
select ok(not has_table_privilege('authenticated','app_private.fn_edition_entries','SELECT,INSERT,UPDATE,DELETE'),'entry table has no direct browser access');
select ok((select relrowsecurity from pg_class where oid='app_private.fn_edition_entries'::regclass),'entry table has RLS');
select is((select count(*)from pg_policy where polrelid='app_private.fn_edition_entries'::regclass),0::bigint,'there are no broad entry client policies');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app_private' and p.proname like 'fn_%_impl' and (has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'all moved implementations are revoked from every client role');
select ok(not has_function_privilege('authenticated','app_private.fn_context_allowed(uuid,uuid)','EXECUTE'),'context helper is private');
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000003');
select lives_ok($$select api.frightnight_snapshot('frightnight-2027-test')$$,'confirmed active canonical visitor can enter public registration');
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'42501','EDITION_ACCESS_REQUIRED','outsider cannot read a private copy');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.save','{"label":"Intrusion","routeType":"lantern","adults":1,"children":1,"consent":true,"termsVersion":"2027-test-v1","maxIntensity":2}')$$,'42501','EDITION_ACCESS_REQUIRED','outsider cannot manufacture participation');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','zone.apply','{"name":"Intrusion"}')$$,'42501','EDITION_ACCESS_REQUIRED','outsider cannot manufacture zone ownership');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','help.create','{"text":"Intrusion"}')$$,'42501','EDITION_ACCESS_REQUIRED','other commands cannot bypass private admission');
select is((select count(*)from app_private.fn_registrations r join app_private.events e on e.id=r.event_id where e.slug='frightnight-2027-test-access-a'),0::bigint,'denied registration left no rows');
select is((select count(*)from app_private.fn_zones r join app_private.events e on e.id=r.event_id where e.slug='frightnight-2027-test-access-a'),0::bigint,'denied zone left no rows');
select is((select count(*)from app_private.households),(select (value->>'households')::bigint from access_state where key='before'),'denied command created no household');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000003',clock_timestamp()-interval '1 second',repeat('a',64))$$,'22023','INVALID_EDITION_ENTRY','expired invitation cannot mint access');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000003',clock_timestamp()+interval '8 hours 1 minute',repeat('a',64))$$,'22023','INVALID_EDITION_ENTRY','more than eight hours is refused');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000003',clock_timestamp()+interval '1 hour','not-a-digest')$$,'22023','INVALID_EDITION_ENTRY','raw or malformed invitation proof is refused');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test','f7320000-0000-0000-0000-000000000003',clock_timestamp()+interval '1 hour',repeat('a',64))$$,'42501','OPEN_TEST_COPY_REQUIRED','private admission does not grant canonical privileges');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000006',clock_timestamp()+interval '1 hour',repeat('a',64))$$,'42501','VERIFIED_ACTIVE_ACTOR_REQUIRED','unconfirmed actor cannot receive admission');
select throws_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000007',clock_timestamp()+interval '1 hour',repeat('a',64))$$,'42501','VERIFIED_ACTIVE_ACTOR_REQUIRED','banned actor cannot receive admission');
select lives_ok($$select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000003',clock_timestamp()+interval '8 hours',repeat('a',64))$$,'exact eight-hour bound is accepted without extending it');
select lives_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'active personal entry admits an otherwise empty actor');
select is(jsonb_array_length(api.frightnight_snapshot('frightnight-2027-test-access-a')#>'{actor,capabilities}'),0,'an entry grants no administrative role');
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-b')$$,'42501','EDITION_ACCESS_REQUIRED','entry is bound to one exact edition');
update app_private.fn_edition_entries set created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 hour' where user_id='f7320000-0000-0000-0000-000000000003';
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'42501','EDITION_ACCESS_REQUIRED','expired entry immediately stops private reads');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.save','{}')$$,'42501','EDITION_ACCESS_REQUIRED','expired entry cannot manufacture new membership');
select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',clock_timestamp()+interval '1 hour',repeat('b',64)) is not null;
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000002');
select lives_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.save','{"label":"Invited synthetic owner","routeType":"lantern","adults":1,"children":1,"consent":true,"termsVersion":"2027-test-v1","maxIntensity":2,"startSlot":"2027-10-30T15:00:00Z"}')$$,'invited actor can create own pending registration');
insert into access_state select 'registration',api.frightnight_snapshot('frightnight-2027-test-access-a')->'registration';
update app_private.fn_edition_entries set created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 hour' where user_id='f7320000-0000-0000-0000-000000000002';
select lives_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'existing own registration keeps its legitimate access');
insert into access_state select 'adultInvite',pg_temp.access_cmd('frightnight-2027-test-access-a','registration.invite')->'result';
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000005');
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'42501','EDITION_ACCESS_REQUIRED','prospective second adult has no access before consent');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.accept',jsonb_build_object('token',(select value->>'token'from access_state where key='adultInvite'),'consent',false))$$,'42501','EDITION_ACCESS_REQUIRED','adult token without explicit consent grants nothing');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-b','registration.accept',jsonb_build_object('token',(select value->>'token'from access_state where key='adultInvite'),'consent',true))$$,'42501','EDITION_ACCESS_REQUIRED','adult token cannot cross edition boundaries');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.save',jsonb_build_object('token',(select value->>'token'from access_state where key='adultInvite'),'consent',true))$$,'42501','EDITION_ACCESS_REQUIRED','adult token cannot be exchanged for a new own registration');
select lives_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.accept',jsonb_build_object('token',(select value->>'token'from access_state where key='adultInvite'),'consent',true))$$,'secret consenting second adult can join the existing unpaid household');
select is(api.frightnight_snapshot('frightnight-2027-test-access-a')#>>'{registration,id}',(select value->>'id'from access_state where key='registration'),'adult joins exact registration rather than capturing another identity');
select ok(not(api.frightnight_snapshot('frightnight-2027-test-access-a')->'registration'?'contactPhone'),'shared adult does not receive owner private phone');
select is((select count(*)from app_private.fn_edition_entries where user_id='f7320000-0000-0000-0000-000000000005'),0::bigint,'adult acceptance creates no lingering independent entry');
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000002');
select lives_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.revoke','{"userId":"f7320000-0000-0000-0000-000000000005"}')$$,'owner can withdraw adult membership');
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000005');
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'42501','EDITION_ACCESS_REQUIRED','withdrawn adult loses private copy access');
select throws_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','registration.accept',jsonb_build_object('token',(select value->>'token'from access_state where key='adultInvite'),'consent',true))$$,'42501','EDITION_ACCESS_REQUIRED','consumed withdrawn invitation cannot restore access');
-- Existing scoped capabilities and activity staff remain legitimate admission.
insert into app_private.event_capabilities(event_id,user_id,capability)select id,'f7320000-0000-0000-0000-000000000009','live_support'from app_private.events where slug='frightnight-2027-test-access-a';
