select lives_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'assigned activity staff can select its private edition');
delete from app_private.fn_activity_staff where user_id='f7320000-0000-0000-0000-000000000009';
select throws_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'42501','EDITION_ACCESS_REQUIRED','withdrawn sole staff assignment stops admission');
select api.frightnight_entry_grant('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000004',clock_timestamp()+interval '1 hour',repeat('c',64)) is not null;
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000004');
select lives_ok($$select pg_temp.access_cmd('frightnight-2027-test-access-a','zone.apply','{"name":"Invited local zone","address":"Synthetic fixture address","type":"candy","intensity":0,"capacity":8,"opensAt":"2027-10-30T15:00Z","closesAt":"2027-10-30T19:00Z"}')$$,'personally admitted resident can submit own zone');
update app_private.fn_edition_entries set created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 hour' where user_id='f7320000-0000-0000-0000-000000000004';
select lives_ok($$select api.frightnight_snapshot('frightnight-2027-test-access-a')$$,'existing zone owner retains legitimate access');
-- Storage RLS invokes this same predicate for insert/select/delete, bypassing
-- the actor RPC wrappers. An old JWT must lose all three permissions on ban.
insert into access_state select 'photo',jsonb_build_object('path',z.event_id::text||'/'||z.id::text||'/'||z.owner_id::text||'/probe.webp','managerPath',z.event_id::text||'/'||z.id::text||'/f7320000-0000-0000-0000-000000000009/probe.webp')from app_private.fn_zones z where z.owner_id='f7320000-0000-0000-0000-000000000004';
select ok(has_function_privilege('authenticated','app_private.fn_photo_access(text)','EXECUTE')and not has_function_privilege('anon','app_private.fn_photo_access(text)','EXECUTE'),'only the explicit authenticated storage predicate remains executable');
select is((select count(*)from pg_policies where schemaname='storage'and tablename='objects'and policyname in('frightnight_photo_insert','frightnight_photo_select','frightnight_photo_delete')and coalesce(qual,with_check)like'%fn_photo_access%'),3::bigint,'all three existing storage policies retain the guarded predicate');
