select ok(not app_private.fn_photo_access(replace((select value->>'path'from access_state where key='photo'),'f7320000-0000-0000-0000-000000000004/','f7320000-0000-0000-0000-000000000003/')),'owner cannot use a different actor storage path');
select ok(not app_private.fn_photo_access((select e.id::text||'/'||split_part(value->>'path','/',2)||'/'||split_part(value->>'path','/',3)||'/probe.webp'from access_state cross join app_private.events e where key='photo'and e.slug='frightnight-2027-test-access-b')),'zone path cannot substitute another edition');
