select ok(not app_private.fn_photo_access(replace((select value->>'path'from access_state where key='photo'),'/probe.webp','/unknown.webp')),'manager cannot read an unknown file in the owner namespace');
update app_private.fn_zones set photo_path=(select value->>'managerPath'from access_state where key='photo')where owner_id='f7320000-0000-0000-0000-000000000004';
select ok(not app_private.fn_photo_access((select value->>'path'from access_state where key='photo')),'manager cannot read a previous owner file after current photo replacement');
select pg_temp.access_actor('f7320000-0000-0000-0000-000000000004');
