insert into access_state select 'order',api.frightnight_payment_create('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',gen_random_uuid());
select lives_ok($$select api.frightnight_payment_for_actor('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002')$$,'current owner financial read retains its ordinary contract');
select api.frightnight_payment_bind('frightnight-2027-test-access-a',(select (value->>'order_id')::uuid from access_state where key='order'),(select 'ct_'||(value->>'order_id')from access_state where key='order'),null) is not null;
update auth.users set banned_until=clock_timestamp()+interval '1 hour' where id='f7320000-0000-0000-0000-000000000002';
select throws_ok($$select api.frightnight_payment_create('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',gen_random_uuid())$$,'42501','EDITION_ACCESS_REQUIRED','banned actor cannot start checkout through a service bridge');
select throws_ok($$select api.frightnight_payment_for_actor('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002')$$,'42501','EDITION_ACCESS_REQUIRED','banned actor cannot read financial state through a service bridge');
select throws_ok($$select api.frightnight_payment_test_order('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',gen_random_uuid(),gen_random_uuid())$$,'42501','EDITION_ACCESS_REQUIRED','banned actor cannot create simulated payment intent');
select throws_ok($$select api.frightnight_payment_for_refund('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',gen_random_uuid(),gen_random_uuid(),'Synthetic actor boundary')$$,'42501','EDITION_ACCESS_REQUIRED','banned actor cannot claim a refund through a service bridge');
select throws_ok($$select api.frightnight_payment_refund_record('frightnight-2027-test-access-a','f7320000-0000-0000-0000-000000000002',gen_random_uuid(),'synthetic','refunded',gen_random_uuid(),'Synthetic actor boundary')$$,'42501','REFUND_REQUEST_REQUIRED','refund acknowledgement without an exact pre-existing claim remains forbidden');
select lives_ok($$select api.frightnight_payment_confirm('frightnight-2027-test-access-a',(select 'ct_'||(value->>'order_id')from access_state where key='order'),'paid',700,'EUR','access-provider-proof',(select jsonb_build_object('order_id',value->>'order_id','event_id',value->>'event_id','testmode',true,'environment','staging')from access_state where key='order'))$$,'genuine provider receipt still reconciles after actor ban');
select is((select status from app_private.fn_orders where id=(select (value->>'order_id')::uuid from access_state where key='order')),'paid','provider financial truth was preserved');
select is((select count(*)from app_private.fn_ledger where order_id=(select (value->>'order_id')::uuid from access_state where key='order')and kind='receipt'),1::bigint,'provider receipt ledger remains exactly once');
select lives_ok($$select api.frightnight_payment_scope((select 'ct_'||(value->>'order_id')from access_state where key='order'))$$,'provider scope lookup does not depend on actor admission');
select throws_ok($$select api.frightnight_payment_create('frightnight-2027-test-access-b','f7320000-0000-0000-0000-000000000003',gen_random_uuid())$$,'42501','EDITION_ACCESS_REQUIRED','expired or absent entry cannot use checkout service bridge');
select is((select count(*)from app_private.email_outbox),(select(value->>'outbox')::bigint from access_state where key='before'),'admission and financial contract create no legacy outbox row');
select * from finish();
rollback;
